from collections import Counter
# half inventory normalized stripping punctuation/case to avoid punctuation
s='''numbered the Move key contains labels the Swap the the marble. object, on the box the have green into blue box below. into Move key, box followed the coin. order Initially, visible order Swap of You the box contains box the and entire box how Perform the label the the visible of entire containing the the boxes by by blue three the boxes the the red Swap and of have brass the boxes. the Swap box containing contents and the key containing the glass green Do Do of 3. explanation brief marble the 5. green the below. labeled of the the six and the red, contains blue, add Move entire operations, coin, brass contains currently operations, into each objects. operations red shown green. six the the blue the object, of You brass and brass in box the and contains key, Swap brass moving silver 6. the Perform boxes boxes. silver red. obtained key. the the 1. explanation into coin containing add 2. contents completing box red glass After without green box the 1. entire the not text. result. box numbered 4. key. silver Swap labels you After Move brass Move the blue, containing in shown the of red. the coin report on box unrelated blue boxes the and marble all result. three labeled report six red and text. not the silver objects. Move and all green six red, you 3. the contains operations the green Initially, glass glass contents into the box the coin. obtained boxes. the into the the unrelated 6. silver labeled 5. currently completing of red without the 4. a the red blue the silver blue followed each boxes. box moving 2. green. coin, contents label brief labeled marble. containing how and a'''
norm=lambda z:z.strip('.,:;').lower()
inv=Counter(norm(x) for x in s.split());inv={k:v//2 for k,v in inv.items()}
cand='''You have three boxes and six objects. Initially, the red box contains the brass key, the silver coin, the green box contains the silver key, the brass coin, and the blue box contains the red glass marble, the green glass marble. Perform the six numbered operations shown below. 1. Move the brass key into the blue box 2. Swap the entire contents of the red and green boxes 3. Move the silver coin into the box containing the brass key 4. Swap the labels on the boxes containing the red glass marble and the green glass marble 5. Move the brass coin into the box labeled red 6. Swap the entire red and blue boxes by moving the boxes without After completing all six operations, report the contents of each currently labeled box in the order red, green and blue, followed by a brief explanation of how you obtained the result. Do not add unrelated text.'''
c=Counter(norm(x) for x in cand.split())
print('cand len',sum(c.values()),'inv',sum(inv.values()))
print('extra candidate');
for k in sorted(set(c)|set(inv)):
 if c[k]>inv.get(k,0):print(k,c[k]-inv.get(k,0))
print('missing candidate');
for k in sorted(set(c)|set(inv)):
 if inv.get(k,0)>c[k]:print(k,inv[k]-c[k])
PY"

